Else { Set tValue = "", tLen = 0}
If 20 > tLen {
	Set tPadding = $get(pPadArray(20 - tLen))
	If tPadding = "" {
		Set $piece(tPadding, $char(32), (20 - tLen + 1)) = ""
		Set pPadArray(20-tLen) = tPadding
	}
	Set tValue = tValue_tPadding
}
